#include <iostream>
#include <vector>
using namespace std;

class Observer {
public:
    virtual void update(int state) = 0;
    virtual ~Observer() {}
};

class Subject {
    int state;
    vector<Observer*> observers;
public:
    void attach(Observer* o) { observers.push_back(o); }
    void setState(int s) { state = s; notify(); }
    void notify() { for (auto o : observers) o->update(state); }
};

class LogObserver : public Observer {
public:
    void update(int state) override { cout << "State: " << state << endl; }
};

class AlertObserver : public Observer {
public:
    void update(int state) override { if (state > 10) cout << "ALERT: state " << state << endl; }
};

int main() {
    Subject subj;
    LogObserver log;
    AlertObserver alert;
    subj.attach(&log);
    subj.attach(&alert);
    subj.setState(5);
    subj.setState(15);
    return 0;
}
